```scala
import cats.stats._

object StatisticsCalculator {

  def main(args: Array[String]): Unit = {

    val dataCSV = DataReader.readCSV("businessData.csv")

    val cleanedData = cleanData(dataCSV)

    val characteristics = List("Revenue", "Age", "Size", "Location", "Industry")
    val weights = calculateWeights(cleanedData)

    characteristics.foreach(characteristic => {
